lab = np.load(WORK/'labels.npy'); N=len(lab); folds=np.load(WORK/'folds.npy'); Y=np.eye(8)[lab]
M=np.load(WORK/'base_mean.npy')
def zs(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def ridge_cv(X, lams):
    res={}
    for lam in lams:
        pred=np.zeros(N,int)
        for f in range(5):
            tr=folds!=f; te=~tr
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6
            Xt=(X[tr]-mu)/sd; Xe=(X[te]-mu)/sd
            K=Xt@Xt.T; a=np.linalg.solve(K+lam*np.eye(len(K)), Y[tr]-Y[tr].mean(0)); S=Xe@(Xt.T@a)
            pred[te]=np.argmax(S,1)
        res[lam]=round((pred==lab).mean(),4)
    return res
for b in [1,2,3,4,6,8,10,11,12]:
    print('m0+m%d'%b, ridge_cv(np.concatenate([M[0],M[b]],1),[100,300]), flush=True)
for a in [1,2,4,8]:
    print('m%d+m11'%a, ridge_cv(np.concatenate([M[a],M[11]],1),[100,300]), flush=True)
# PCA-k of m0 appended to m11 (pca unsupervised on all data)
Z0=zs(M[0]); U,S,Vt=np.linalg.svd(Z0,full_matrices=False)
for k in [8,16,32,64,128]:
    X=np.concatenate([M[11], Z0@Vt[:k].T],1)
    print('m11+pca%d(m0)'%k, ridge_cv(X,[100,300]), flush=True)
